import React, { useState, useEffect } from 'react';
import { fetchResorts, fetchResort } from './api';
import './App.css';

function App() {
  const [resorts, setResorts] = useState([]);
  const [selectedResort, setSelectedResort] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const getResorts = async () => {
      try {
        const data = await fetchResorts();
        setResorts(data);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };
    getResorts();
  }, []);

  const handleSearchChange = (e) => {
    setSearchTerm(e.target.value);
  };

  const handleResortClick = async (name) => {
    try {
      const data = await fetchResort(name);
      setSelectedResort(data);
    } catch (err) {
      setError(err.message);
    }
  };

  const filteredResorts = resorts.filter(resort =>
    resort.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;

  return (
    <div>
      <h1>Ski Resorts</h1>
      <input
        type="text"
        placeholder="Search for a resort..."
        value={searchTerm}
        onChange={handleSearchChange}
        className="search-input"
      />
      <ul>
        {filteredResorts.length > 0 ? (
          filteredResorts.map((resort) => (
            <li key={resort.id} onClick={() => handleResortClick(resort.name)}>
              {resort.name}
            </li>
          ))
        ) : (
          <li>No resorts found</li>
        )}
      </ul>
      {selectedResort && (
        <div className="resort-details">
          <h2>{selectedResort.name}</h2>
          <p>{selectedResort.description}</p>
        </div>
      )}
    </div>
  );
}

export default App;
